// Логика бота: какой экран показать и что запомнить между сообщениями.
// Тексты, кнопки и товары НЕ здесь — они в таблицах bot_screens и bot_products
// (правятся формой «Админка контента» в n8n или в базе). Сюда они приходят
// строкой из ноды «Состояние и контент»: $json.screens, $json.products.
//
// Вход:  $('Вернуть событие') — событие, $json — состояние диалога + контент.
// Выход: { action, reply, state, order }
//   action: 'reply' — показать экран | 'order' — оформить заказ |
//           'rates' — сходить за курсом | 'myorders' — выбрать заказы
//   reply:  { chat_id, user_id, callback_id, text, buttons } — вход «Отправить в MAX»
//   state:  новое состояние диалога или null, чтобы очистить

const ev = $('Вернуть событие').first().json;
const st = $json ?? {};
const SCREENS = st.screens ?? {};
const PRODUCTS = st.products ?? [];                       // уже отсортированы по sort
const product = (id) => PRODUCTS.find((p) => p.id === id);
const state = { screen: st.screen ?? 'main', step: st.step ?? null, data: st.data ?? {} };

// Сколько живёт незаконченная форма. Дальше её убирает prune_bot_events().
const FORM_TTL_MINUTES = 30;
const money = (n) => Number(n).toLocaleString('ru-RU') + ' ₽';

// ─────────────────────────────────────────── шаблоны
// {name} в тексте или кнопке заменяется на vars.name; неизвестные остаются как есть.
const fill = (v, vars) =>
  typeof v === 'string' ? v.replace(/\{(\w+)\}/g, (m, k) => (k in vars ? String(vars[k]) : m))
  : Array.isArray(v) ? v.map((x) => fill(x, vars))
  : v && typeof v === 'object' ? Object.fromEntries(Object.entries(v).map(([k, x]) => [k, fill(x, vars)]))
  : v;

const base = { name: ev.name ?? '', user_id: ev.user_id, chat_id: ev.chat_id };
const productVars = (p) => ({ id: p.id, title: p.title, short: p.short, description: p.description, price: money(p.price_rub) });

// Экран из bot_screens с подстановкой. extraRows — собранные в коде ряды кнопок
// (каталог), они идут перед кнопками из шаблона.
function screen(key, vars = {}, extraRows = []) {
  const s = SCREENS[key] ?? {
    text: `⚠️ Экран «${key}» не найден в bot_screens.`,
    buttons: [[{ type: 'callback', text: '⬅️ В меню', payload: 'main' }]],
  };
  const all = { ...base, ...vars };
  return { text: fill(s.text, all), buttons: [...extraRows, ...fill(s.buttons ?? [], all)] };
}

const catalog = () => screen('catalog', {}, PRODUCTS.filter((p) => p.active !== false).map((p) => [{
  type: 'callback',
  text: fill(SCREENS.catalog_button?.text ?? '{title} — {price}', productVars(p)),
  payload: `item:${p.id}`,
}]));

// Телефон из текста: 10-15 цифр, лишнее отбрасываем.
function parsePhone(text) {
  const digits = (text || '').replace(/[^\d+]/g, '');
  return /^\+?\d{10,15}$/.test(digits) ? digits : null;
}

// ─────────────────────────────────────────── сборка ответа
// Адрес ответа для «Отправить в MAX»: нажатие кнопки — правка на месте, иначе новое сообщение.
const reply = (scr) => ({
  chat_id: ev.chat_id, user_id: ev.user_id,
  callback_id: ev.kind === 'callback' ? (ev.callback_id ?? null) : null,
  ...scr,
});
const out = (scr, opts = {}) => [{
  json: {
    action: opts.action ?? 'reply',
    reply: scr ? reply(scr) : null,
    state: opts.state ?? null,
    order: opts.order ?? null,
    ttl_minutes: FORM_TTL_MINUTES,
  },
}];

const key = ev.kind === 'callback' ? (ev.payload || 'main') : '';
const text = ev.text || '';

// ── 1. Форма заказа перехватывает ввод раньше меню: пока идёт шаг, число или
//       телефон означают ответ на вопрос, а не команду.
if (state.screen === 'order' && key !== 'cancel' && !key.startsWith('item:')
    && key !== 'main' && key !== 'catalog') {
  const pid = state.data.product_id;
  const p = product(pid);
  if (!p) return out(catalog(), { state: null });          // товар исчез из каталога
  const pv = productVars(p);

  if (state.step === 'qty') {
    const qty = key.startsWith('qty:') ? Number(key.slice(4)) : Number(text.replace(/\s/g, ''));
    if (!Number.isInteger(qty) || qty < 1 || qty > 99) {
      return out(screen('order_qty_bad', pv), { state: { screen: 'order', step: 'qty', data: state.data } });
    }
    return out(screen('order_phone', { ...pv, qty, total: money(p.price_rub * qty) }),
      { state: { screen: 'order', step: 'phone', data: { ...state.data, qty } } });
  }

  if (state.step === 'phone') {
    const phone = ev.contact_phone ?? parsePhone(text);
    if (!phone) {
      return out(screen('order_phone_bad', pv), { state: { screen: 'order', step: 'phone', data: state.data } });
    }
    // Заказ собран. Ответ соберётся после вставки в БД — нужен его номер.
    return out(null, { action: 'order', state: null, order: {
      product_id: pid, product_title: p.title, qty: state.data.qty,
      price_rub: p.price_rub, total_rub: p.price_rub * state.data.qty, phone,
    } });
  }
}

// ── 2. Экраны по кнопкам
if (key === 'cancel') return out(screen('cancel'), { state: null });
if (key === 'catalog') return out(catalog());
if (key.startsWith('item:')) {
  const p = product(key.slice(5));
  return out(p ? screen('item', productVars(p)) : catalog());
}
if (key.startsWith('order:')) {
  const p = product(key.slice(6));
  if (!p) return out(catalog());
  return out(screen('order_qty', productVars(p)), { state: { screen: 'order', step: 'qty', data: { product_id: p.id } } });
}
// Курс и заказы уходят за данными — экран соберётся после запроса.
if (key === 'rates' || /^\/(rates|курс)$/i.test(text)) return out(null, { action: 'rates' });
if (key === 'myorders' || /^\/orders$/i.test(text)) return out(null, { action: 'myorders' });

// ── 3. Текстовые команды и вложения
if (/^\/whoami$/i.test(text)) return out(screen('whoami'));
if (ev.geo) return out(screen('geo', { lat: ev.geo.lat.toFixed(4), lon: ev.geo.lon.toFixed(4) }));
if (/^эхо\s+/i.test(text)) return out(screen('echo', { echo: text.replace(/^эхо\s+/i, '') }));

// ── 4. Любой известный экран по его ключу (about, delivery, faq… — что угодно
//       из bot_screens). Новый экран = строка в таблице + кнопка с таким payload.
if (key && key !== 'main' && SCREENS[key]) return out(screen(key));

// Всё остальное, включая /start и неизвестный payload, — главное меню.
return out(screen('main'), { state: null });

// Заказ уже в базе, номер известен. Собираем два сообщения по шаблонам
// order_done (клиенту) и order_admin (каждому из ADMIN_IDS) — оба уходят
// одним «Отправить в MAX», просто разными items.
const ev = $('Вернуть событие').first().json;
const S = $('Состояние и контент').first().json.screens ?? {};
const o = $('Сценарий').first().json.order;
const row = $json;                                   // строка из «Создать заказ»
const money = (n) => Number(n).toLocaleString('ru-RU') + ' ₽';
const vars = {
  order_id: row.id, title: o.product_title, qty: o.qty, total: money(o.total_rub), phone: o.phone,
  client: `${ev.name}${ev.username ? ' (@' + ev.username + ')' : ''}, id ${ev.user_id}`,
};
const fill = (s) => (s ?? '').replace(/\{(\w+)\}/g, (m, k) => (k in vars ? String(vars[k]) : m));

const items = [{ json: {
  chat_id: ev.chat_id, user_id: ev.user_id, callback_id: null,
  text: fill(S.order_done?.text ?? '✅ Заказ №{order_id} принят!'),
  buttons: S.order_done?.buttons ?? [],
} }];

// ADMIN_IDS — user_id через запятую. Пусто — уведомлять некого, заказ всё равно
// лежит в базе. Свой id подскажет /whoami.
const admins = String($env.ADMIN_IDS ?? '').split(',').map((s) => s.trim()).filter(Boolean);
for (const id of admins) {
  items.push({ json: {
    chat_id: null, user_id: id, callback_id: null,
    text: fill(S.order_admin?.text ?? '🔔 Новый заказ №{order_id}'),
    buttons: S.order_admin?.buttons ?? [],
  } });
}
return items;

// Ответ ЦБ РФ -> экран rates. Главный довод в пользу n8n: сходить во внешний API
// и подмешать данные в ответ — одна нода HTTP Request.
const ev = $('Вернуть событие').first().json;
const S = $('Состояние и контент').first().json.screens ?? {};
// Нода настроена на JSON, но если ответ придёт строкой (ЦБ сменит content-type),
// разберём сами — экран не должен пустеть.
const raw = $json ?? {};
const d = raw.Valute ? raw : JSON.parse(raw.data ?? raw.body ?? '{}');
const v = d.Valute ?? {};
const fmt = (c) => (v[c] ? `${v[c].Name}: *${v[c].Value.toFixed(2)} ₽* (${v[c].Previous > v[c].Value ? '↓' : '↑'})` : null);
const vars = {
  rates_lines: ['USD', 'EUR', 'CNY'].map(fmt).filter(Boolean).join('\n'),
  rates_date: (d.Date ?? '').slice(0, 10).split('-').reverse().join('.'),
};
const fill = (s) => (s ?? '').replace(/\{(\w+)\}/g, (m, k) => (k in vars ? String(vars[k]) : m));
return [{ json: {
  chat_id: ev.chat_id, user_id: ev.user_id,
  callback_id: ev.kind === 'callback' ? (ev.callback_id ?? null) : null,
  text: fill(S.rates?.text ?? '💱 {rates_lines}'),
  buttons: S.rates?.buttons ?? [],
} }];

// Список заказов пользователя -> экран myorders или myorders_empty.
const ev = $('Вернуть событие').first().json;
const S = $('Состояние и контент').first().json.screens ?? {};
const rows = $input.all().map((i) => i.json).filter((r) => r.id);
const money = (n) => Number(n).toLocaleString('ru-RU') + ' ₽';
const orders = rows.map((r) =>
  `*№${r.id}* — ${r.product_title} × ${r.qty}\n${money(r.total_rub)} · ${r.status} · `
  + new Date(r.created_at).toLocaleDateString('ru-RU')).join('\n\n');
const s = rows.length ? S.myorders : S.myorders_empty;
return [{ json: {
  chat_id: ev.chat_id, user_id: ev.user_id,
  callback_id: ev.kind === 'callback' ? (ev.callback_id ?? null) : null,
  text: (s?.text ?? '{orders}').replace('{orders}', orders),
  buttons: s?.buttons ?? [],
} }];
